package com.rudra.offlinepayment;
import android.Manifest;import android.app.Activity;import android.bluetooth.*;import android.bluetooth.le.*;import android.content.*;import android.content.pm.PackageManager;import android.os.*;import android.widget.*;import java.nio.charset.StandardCharsets;import java.util.*;
import com.rudra.offlinepayment.ble.BleContract;
public class BleSendActivity extends Activity {
 BluetoothLeScanner scanner;BluetoothGatt gatt;TextView status;String payload;boolean scanning=false;
 final ScanCallback scanCallback=new ScanCallback(){@Override public void onScanResult(int type,ScanResult result){if(scanning){scanning=false;scanner.stopScan(this);status.setText("Relay found. Connecting…");gatt=result.getDevice().connectGatt(BleSendActivity.this,false,gattCallback);}}@Override public void onScanFailed(int e){status.setText("BLE scan failed: "+e);}};
 final BluetoothGattCallback gattCallback=new BluetoothGattCallback(){
  @Override public void onConnectionStateChange(BluetoothGatt g,int s,int state){if(state==BluetoothProfile.STATE_CONNECTED){g.discoverServices();}else if(state==BluetoothProfile.STATE_DISCONNECTED)runOnUiThread(()->status.setText("Disconnected. Check relay and retry."));}
  @Override public void onServicesDiscovered(BluetoothGatt g,int s){BluetoothGattService service=g.getService(BleContract.SERVICE);BluetoothGattCharacteristic c=service==null?null:service.getCharacteristic(BleContract.PAYMENT);if(c==null){runOnUiThread(()->status.setText("Relay protocol service not found."));return;}byte[] bytes=payload.getBytes(StandardCharsets.UTF_8);if(bytes.length>BleContract.MAX_PAYLOAD_BYTES){runOnUiThread(()->status.setText("Intent too large for this demo BLE frame."));return;}c.setWriteType(BluetoothGattCharacteristic.WRITE_TYPE_DEFAULT);c.setValue(bytes);boolean ok=g.writeCharacteristic(c);runOnUiThread(()->status.setText(ok?"Intent sent to relay. Wait for relay backend confirmation.":"BLE write could not start."));}
  @Override public void onCharacteristicWrite(BluetoothGatt g,BluetoothGattCharacteristic c,int s){runOnUiThread(()->status.setText(s==BluetoothGatt.GATT_SUCCESS?"Relay received the intent. Backend sync happens on relay.":"Relay write failed: "+s));}
 };
 @Override public void onCreate(Bundle b){super.onCreate(b);payload=getIntent().getStringExtra("payload");LinearLayout l=new LinearLayout(this);l.setPadding(28,32,28,20);l.setOrientation(1);setContentView(l);status=new TextView(this);status.setText("Ready to find a nearby relay.");l.addView(status);Button start=new Button(this);start.setText("Find relay and transfer");l.addView(start);start.setOnClickListener(v->start());}
 void start(){if(Build.VERSION.SDK_INT>=31&&(checkSelfPermission(Manifest.permission.BLUETOOTH_SCAN)!=PackageManager.PERMISSION_GRANTED||checkSelfPermission(Manifest.permission.BLUETOOTH_CONNECT)!=PackageManager.PERMISSION_GRANTED)){requestPermissions(new String[]{Manifest.permission.BLUETOOTH_SCAN,Manifest.permission.BLUETOOTH_CONNECT},4);return;}BluetoothManager m=getSystemService(BluetoothManager.class);BluetoothAdapter a=m.getAdapter();if(a==null||!a.isEnabled()){status.setText("Enable Bluetooth on this phone.");return;}scanner=a.getBluetoothLeScanner();ScanFilter f=new ScanFilter.Builder().setServiceUuid(new android.os.ParcelUuid(BleContract.SERVICE)).build();ScanSettings settings=new ScanSettings.Builder().setScanMode(ScanSettings.SCAN_MODE_LOW_LATENCY).build();scanning=true;scanner.startScan(Collections.singletonList(f),settings,scanCallback);status.setText("Scanning for relay (15 seconds)…");new Handler(Looper.getMainLooper()).postDelayed(()->{if(scanning){scanning=false;scanner.stopScan(scanCallback);status.setText("No relay found. Keep relay app open nearby and retry.");}},15000);}
 @Override public void onRequestPermissionsResult(int r,String[] p,int[] g){super.onRequestPermissionsResult(r,p,g);if(r==4&&g.length>0&&g[0]==PackageManager.PERMISSION_GRANTED)start();else status.setText("Bluetooth permissions are required.");}
 @Override protected void onDestroy(){super.onDestroy();if(scanner!=null&&scanning)scanner.stopScan(scanCallback);if(gatt!=null){gatt.disconnect();gatt.close();}}
}